class Solution {
public:
    int GCD(int n1,int n2) {
        n1 = n1 < 0 ? -n1 : n1;
        n2 = n2 < 0 ? -n2 : n2;

        while (n2 != 0) {
            int remainder = n1 % n2;
            n1 = n2;
            n2 = remainder;
        }

        return n1;
    }
};
```

Time complexity: `O(log(min(n1, n2)))` for positive inputs.
Space complexity: `O(1)`.

